#include <string>
using namespace std;

template <typename T>
void swap2(T& a, T& b) {
    T t = a;
    a = b;
    b = t;
}

int main() {
    int a = 0;
    int b = 0;
    cin >> a >> b;

    swap2(a, b);

    cout << "小橘：" << a << endl;
    cout << "大肥鱼：" << b << endl;
    return 0;
}

